mapper.sql:
WHERE 1=1

	AND request_tracking_id = #{requestTrackingId}


	AND tracking_process_id = #{trackingProcessId}


	AND msg_status = #{msgStatus}


	AND transmission_status = #{transmissionStatus}


	 AND transmission_time >= #{fromTime} 


	 AND transmission_time <= #{toTime}

mapper.select:
SELECT status_transmission_id, request_tracking_id, tracking_process_id, msg_status, last_observed_at, no_data_refs, DATE_FORMAT(checked_time, '%Y-%m-%d %H:%i:%s') checked_time, DATE_FORMAT(transmission_time, '%Y-%m-%d %H:%i:%s.%f') transmission_time, transmission_status, transmission_url, transmission_param, transmission_resp_code, transmission_resp_msg FROM tracking_status_transmission_info
ORDER BY status_transmission_id DESC
LIMIT #{start}, #{end}

mapper.delete:
DELETE s FROM tracking_status_transmission_info s INNER JOIN data_event_tracking_request_info q ON q.request_tracking_id = s.request_tracking_id WHERE q.req_trck_cmd_status IN
#{item}
AND q.req_status_change_time < DATE_SUB(NOW(), INTERVAL #{retentionDays} DAY)
